 private static int queryInteger(Map<String,String> query,String field,int fallback,int maximum){String value=query.get(field);if(value==null||value.isBlank())return fallback;try{int number=Integer.parseInt(value);if(number<1||number>maximum)throw Inputs.bad("分页参数超出范围");return number;}catch(NumberFormatException invalid){throw Inputs.bad("分页参数不合法");}}
 private boolean matchesQuery(String kind,Map<String,Object> row,Map<String,String> query,Map<String,Long> ids){
  for(String field:List.of("bookId","entityId","supplierId"))if(ids.containsKey(field)&&!Objects.equals(ids.get(field),row.get(field) instanceof Number n?n.longValue():null))return false;
  if(ids.containsKey("productId")&&castLines(row).stream().noneMatch(line->id(line,"productId")==ids.get("productId")))return false;
  if(ids.containsKey("orderId")){long order=ids.get("orderId");if(kind.equals("orders")?id(row,"id")!=order:kind.equals("domestic-receipts")?id(row,"orderId")!=order:castLines(row).stream().noneMatch(line->id(line,"poId")==order))return false;}
  String status=query.get("status");if(status!=null&&!status.isBlank()&&!status.equals(row.get("status")))return false;
  String docNo=query.get("docNo");if(docNo!=null&&!docNo.isBlank()&&!contains(row.get("docNo"),docNo))return false;
  String keyword=query.get("keyword");if(keyword==null||keyword.isBlank())return true;
  return (kind.equals("orders")?List.of("docNo"):kind.equals("domestic-receipts")?List.of("docNo","orderNo","location"):List.of("docNo","declarationNo","exportPort")).stream().anyMatch(field->contains(row.get(field),keyword));
 }
 private static boolean contains(Object value,String keyword){return value!=null&&value.toString().toLowerCase(Locale.ROOT).contains(keyword.toLowerCase(Locale.ROOT));}
