   out.put("totalQualified",rows.stream().map(this::qualifiedInspectionQty).reduce(BigDecimal.ZERO,BigDecimal::add));out.put("totalPending",rows.stream().map(this::pendingInspectionQty).reduce(BigDecimal.ZERO,BigDecimal::add));out.put("totalDamaged",rows.stream().map(row->q(row,"damagedQty").add(q(row,"convertedDamagedQty"))).reduce(BigDecimal.ZERO,BigDecimal::add));
